    if not arr:
        return None

    product_of_signs = 1    sum_of_magnitudes = 0

    for num in arr:
        sum_of_magnitudes += abs(num)
        if num == 0:
            product_of_signs = 0
        elif num < 0:
            product_of_signs *=-1 
    return sum_of_magnitudes * product_of_signs
