        if n <= 1:
            return False
        if n <= 3:
            return True
        if n %2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i ==0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    start1, end1 = interval1
    start2, end2 = interval2
    intersection_start = max(start1, start2)
    intersection_end = min(end1, end2)

    if intersection_start > intersection_end:
        return "NO"

    intersection_length = intersection_end - intersection_start + 1    returnYES if is_prime(intersection_length) else "NO"
