def is_nested(string):
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']' and stack:
            stack.pop()
        # If we find a closing bracket and the stack is empty, it means there's an unmatched closing bracket
        elif char == ']' and not stack:
            return False
    # If the stack is not empty, it means there are unmatched opening brackets
    # We need to check if there was any nesting
    return len(stack) < len(string) // 2
